css:
@import url("https://fonts.googleapis.com/css2?family=Schibsted+Grotesk:wght@400;500;700;800&display=swap");
:root{--slate:#0F172A;--slate-2:#334155;--em:#0F9D6B;--em-d:#0B7A53;--mint:#ECF8F2;--amber:#F59E0B;--rose:#F43F5E;--sky:#0EA5E9;--bg:#F8FAFC;--text:#1E293B;--muted:#64748B;--line:#E2E8F0;
--font:"Schibsted Grotesk",system-ui,-apple-system,"Segoe UI",sans-serif;--wrap:1200px}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}
body{margin:0;font-family:var(--font);font-size:18px;line-height:1.6;color:var(--text);background:#fff;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}a{color:inherit}p{margin:0 0 1em}
h1,h2,h3{font-weight:800;margin:0;line-height:1.05;color:var(--slate);letter-spacing:-.03em}h3{font-weight:700;letter-spacing:-.01em}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 22px}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--amber);padding:10px;z-index:99}
:focus-visible{outline:3px solid var(--em);outline-offset:3px;border-radius:6px}
.site-header{position:sticky;top:0;z-index:40;background:rgba(255,255,255,.94);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
.nav{display:flex;align-items:center;justify-content:space-between;height:70px}
.logo{display:flex;align-items:center;gap:10px;font-weight:800;font-size:22px;text-decoration:none;color:var(--slate)}
.logo i{width:28px;height:28px;border-radius:8px;background:var(--em);display:flex;gap:3px;padding:6px}.logo i::before,.logo i::after{content:"";flex:1;background:#fff;border-radius:2px}.logo i::after{height:60%}
.menu{display:flex;gap:28px;list-style:none;margin:0;padding:0}.menu a{text-decoration:none;font-weight:500;color:var(--slate-2)}.menu a:hover{color:var(--em)}
.nav-cta{display:flex;gap:10px;align-items:center}.nav-cta .login{font-weight:500;text-decoration:none;color:var(--slate-2)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:12px 22px;border-radius:10px;font-weight:700;text-decoration:none;border:1px solid transparent;font-family:var(--font);font-size:16px;cursor:pointer}
.btn-em{background:var(--em);color:#fff}.btn-em:hover{background:var(--em-d)}
.btn-slate{background:var(--slate);color:#fff}.btn-out{border-color:var(--line);background:#fff;color:var(--slate)}.btn-out:hover{border-color:var(--slate)}
.burger{display:none;background:none;border:1px solid var(--line);border-radius:10px;padding:9px 11px;cursor:pointer}.burger span{display:block;width:20px;height:2px;background:var(--slate);margin:4px 0}
.hero{padding:80px 0 0;text-align:center;background:linear-gradient(180deg,var(--mint),#fff 60%)}
.hero h1{font-size:clamp(42px,6.4vw,82px);max-width:16ch;margin:0 auto}
.hero h1 span{color:var(--em)}
.hero .lead{font-size:21px;color:var(--muted);max-width:52ch;margin:22px auto 30px}
.actions{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}
.fine{font-size:15px;color:var(--muted);margin:16px 0 0}
.app{margin:60px auto 0;max-width:1080px;background:#fff;border:1px solid var(--line);border-radius:18px 18px 0 0;box-shadow:0 -10px 60px -30px rgba(15,23,42,.35);overflow:hidden;text-align:left;display:grid;grid-template-columns:200px 1fr}
.side{background:var(--bg);border-right:1px solid var(--line);padding:18px 14px;font-size:14px}
.side b{display:block;font-size:12px;color:var(--muted);margin:14px 8px 6px}
.side a{display:flex;gap:8px;align-items:center;padding:8px;border-radius:8px;text-decoration:none;color:var(--slate-2)}
.side a.on{background:#fff;border:1px solid var(--line);color:var(--slate);font-weight:700}
.side i{width:10px;height:10px;border-radius:3px}
.board{padding:18px}
.board-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}
.board-top h3{font-size:18px}
.avs{display:flex}.avs img{width:30px;height:30px;border-radius:50%;border:2px solid #fff;margin-left:-8px;object-fit:cover}
.cols{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.col{background:var(--bg);border-radius:12px;padding:10px}
.col h4{margin:2px 4px 10px;font-size:13px;color:var(--muted);display:flex;justify-content:space-between}
.task{background:#fff;border:1px solid var(--line);border-radius:10px;padding:10px 12px;margin-bottom:8px;font-size:14px}
.task b{display:block;font-weight:500;color:var(--slate);margin-bottom:6px}
.chip{display:inline-block;font-size:11px;font-weight:700;padding:2px 8px;border-radius:999px;margin-right:4px}
.c1{background:#E0F2FE;color:#0369A1}.c2{background:#FEF3C7;color:#92400E}.c3{background:#FFE4E6;color:#9F1239}.c4{background:var(--mint);color:var(--em-d)}
.prog{height:5px;background:var(--line);border-radius:3px;margin-top:8px}.prog i{display:block;height:100%;background:var(--em);border-radius:3px}
.logos{padding:40px 0;border-bottom:1px solid var(--line)}
.logos p{text-align:center;color:var(--muted);font-size:15px;margin-bottom:18px}
.logos .row{display:flex;justify-content:center;gap:48px;flex-wrap:wrap}.logos .row span{font-weight:800;font-size:21px;color:#A0AEC0}
section{padding:110px 0}
.head{text-align:center;max-width:740px;margin:0 auto 56px}.head h2{font-size:clamp(34px,4.4vw,56px)}.head p{color:var(--muted);font-size:19px;margin-top:14px}
.feat-row{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center;margin-bottom:90px}
.feat-row:last-child{margin-bottom:0}
.feat-row:nth-child(even) .fr-img{order:2}
.fr-img{border-radius:20px;overflow:hidden;border:1px solid var(--line)}.fr-img img{width:100%;aspect-ratio:4/3;object-fit:cover}
.feat-row h3{font-size:clamp(28px,3vw,40px);margin-bottom:14px}.feat-row p{color:var(--muted)}
.ticks{list-style:none;padding:0;margin:18px 0 0}.ticks li{padding:6px 0 6px 30px;position:relative}
.ticks li::before{content:"✓";position:absolute;left:0;top:6px;width:20px;height:20px;border-radius:50%;background:var(--mint);color:var(--em);font-size:12px;font-weight:800;display:grid;place-items:center}
.label{color:var(--em);font-weight:700;font-size:15px;display:block;margin-bottom:10px}
.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.mini{border:1px solid var(--line);border-radius:16px;padding:24px}
.mini h3{font-size:19px;margin-bottom:6px}.mini p{margin:0;color:var(--muted);font-size:16px}
.int{background:var(--slate);color:#CBD5E1}
.int h2{color:#fff}.int .head p{color:#94A3B8}
.tiles{display:grid;grid-template-columns:repeat(6,1fr);gap:12px}
.tiles span{background:#1E293B;border:1px solid var(--slate-2);border-radius:14px;padding:22px 10px;text-align:center;font-weight:700;color:#fff}
.pricing .toggle{display:inline-flex;background:var(--bg);border:1px solid var(--line);border-radius:999px;padding:4px;margin-top:22px}
.toggle button{border:0;background:none;font:inherit;font-weight:700;font-size:15px;padding:8px 18px;border-radius:999px;cursor:pointer;color:var(--slate-2)}
.toggle button[aria-pressed="true"]{background:var(--slate);color:#fff}
.save{color:var(--em);font-weight:700;font-size:14px;margin-left:8px}
.plans{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.plan{border:1px solid var(--line);border-radius:20px;padding:30px;display:flex;flex-direction:column}
.plan.hot{border:2px solid var(--em);background:linear-gradient(180deg,var(--mint),#fff 35%)}
.plan h3{font-size:22px}.plan .desc{color:var(--muted);font-size:15px;margin:4px 0 0}
.plan .amt{font-size:50px;font-weight:800;color:var(--slate);margin:16px 0 0;letter-spacing:-.03em}
.plan .amt small{font-size:16px;font-weight:500;color:var(--muted)}
.plan .per{font-size:14px;color:var(--muted);min-height:22px}
.plan ul{list-style:none;padding:0;margin:18px 0 26px;font-size:16px}.plan li{padding:7px 0 7px 26px;position:relative}
.plan li::before{content:"✓";position:absolute;left:0;color:var(--em);font-weight:800}
.plan .btn{margin-top:auto}
.tablewrap{overflow-x:auto;margin-top:50px}
table{width:100%;border-collapse:collapse;min-width:640px;font-size:16px}
th,td{padding:14px 16px;border-bottom:1px solid var(--line);text-align:center}
th:first-child,td:first-child{text-align:left}
thead th{font-size:17px;color:var(--slate)}
td.y{color:var(--em);font-weight:800}td.n{color:#CBD5E1}
.quotes{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.q{background:var(--bg);border-radius:18px;padding:26px;margin:0}
.q p{font-size:17px}.q .who{display:flex;gap:12px;align-items:center}.q img{width:44px;height:44px;border-radius:50%;object-fit:cover}
.q b{display:block;font-size:15px}.q span{font-size:14px;color:var(--muted)}
.faq{max-width:820px;margin:0 auto}
.faq details{border-bottom:1px solid var(--line);padding:18px 0}
.faq summary{list-style:none;cursor:pointer;font-weight:700;font-size:19px;display:flex;justify-content:space-between;gap:18px;color:var(--slate)}
.faq summary::-webkit-details-marker{display:none}.faq summary::after{content:"+";font-size:24px;line-height:1;color:var(--em)}
.faq details[open] summary::after{content:"−"}.faq details p{margin:10px 0 0;color:var(--muted)}
.cta{background:var(--em);color:#DDF5EA;text-align:center}
.cta h2{color:#fff;font-size:clamp(36px,5vw,64px);max-width:18ch;margin:0 auto}
.cta p{font-size:20px;margin:18px 0 28px}
.cta .btn-out{border-color:#fff}
footer{background:var(--slate);color:#94A3B8;padding:56px 0 30px;font-size:15px}
.foot{display:grid;grid-template-columns:1.4fr repeat(3,1fr);gap:30px;margin-bottom:36px}
footer .logo{color:#fff}footer h3{color:#fff;font-size:15px;margin-bottom:12px}
footer ul{list-style:none;padding:0;margin:0}footer li{margin-bottom:8px}footer a{text-decoration:none}footer a:hover{color:#fff}
.legal{border-top:1px solid #1E293B;padding-top:20px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}
@media (max-width:1000px){.menu,.nav-cta{display:none}.burger{display:block}
.menu.open{display:flex;flex-direction:column;position:absolute;top:70px;left:0;right:0;background:#fff;padding:22px;border-bottom:1px solid var(--line);gap:16px}
.app{grid-template-columns:1fr}.side{display:none}
.feat-row{grid-template-columns:1fr;gap:30px}.feat-row:nth-child(even) .fr-img{order:0}
.grid3,.plans,.quotes{grid-template-columns:1fr 1fr}.tiles{grid-template-columns:repeat(3,1fr)}.foot{grid-template-columns:1fr 1fr}}
@media (max-width:600px){body{font-size:17px}section{padding:76px 0}.cols{grid-template-columns:1fr}.col:nth-child(n+2){display:none}.grid3,.plans,.quotes{grid-template-columns:1fr}.tiles{grid-template-columns:1fr 1fr}}
